describe('Public shopping account-link entry; authentication not submitted', () => {
  beforeEach(() => cy.viewport(1366, 900));

  it('AUTH-ENTRY01 — the intended product account link reaches the guest login form', () => {
    visitGuest(products.simple.path);
    cy.location('pathname').should('eq', products.simple.path);
    cy.get('main h1').should('have.text', products.simple.name).and('be.visible');
    followAccountLink();
  });

  it('AUTH-ENTRY02 — the empty-cart account link reaches the guest login form', () => {
    visitGuest('/cart');
    cy.location('pathname').should('eq', '/cart');
    cy.get('main [data-cy="cart-item"]').should('not.exist');
    cy.get('main .commerce-empty').should('have.length', 1).and('be.visible');
    followAccountLink();
  });
});
